// Generated by npm run build. Edit src/scripts/chatbot.mjs instead.
const combiningMarks = /\p{M}/gu;

export function normalizeChatText(value) {
  return String(value)
    .toLocaleLowerCase()
    .normalize('NFD')
    .replace(combiningMarks, '')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ـ/g, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

export function matchChatIntent(question, intents) {
  const query = normalizeChatText(question);
  if (!query) return null;

  const paddedQuery = ` ${query} `;
  const matches = [];
  for (const intent of intents) {
    const matchedTerms = (intent.terms || [])
      .map(term => normalizeChatText(term))
      .filter(term => term && paddedQuery.includes(` ${term} `));
    if (matchedTerms.length) {
      matches.push({
        intent,
        specificity: Math.max(...matchedTerms.map(term => term.split(' ').length)),
        coverage: matchedTerms.length,
        firstPosition: Math.min(...matchedTerms.map(term => paddedQuery.indexOf(` ${term} `)))
      });
    }
  }

  if (!matches.length) return null;
  const portfolioMatches = matches.filter(({ intent }) =>
    !['greeting', 'thanks', 'help'].includes(intent.id)
  );
  const candidates = portfolioMatches.length ? portfolioMatches : matches;
  candidates.sort((left, right) =>
    right.specificity - left.specificity || right.coverage - left.coverage ||
    (!portfolioMatches.length ? left.firstPosition - right.firstPosition : 0)
  );
  const [best, next] = candidates;
  if (next && next.specificity === best.specificity && next.coverage === best.coverage && portfolioMatches.length) return null;
  return best.intent;
}

function initializeChatbot() {
  const root = document.querySelector('[data-portfolio-chat]');
  if (!root) return;

  const dataElement = document.getElementById('chatbot-data');
  let data;
  try {
    data = JSON.parse(dataElement?.textContent || '');
  } catch {
    return;
  }
  if (!data?.intents || !Array.isArray(data.intents)) return;

  const panel = root.querySelector('.chatbot-panel');
  const launcher = root.querySelector('.chatbot-launcher');
  const closeButton = root.querySelector('.chatbot-close');
  const form = root.querySelector('.chatbot-form');
  const input = root.querySelector('#chatbot-question');
  const messages = root.querySelector('.chatbot-messages');
  if (!panel || !launcher || !closeButton || !form || !input || !messages) return;

  function addMessage(text, kind) {
    const message = document.createElement('p');
    message.className = `chatbot-message chatbot-message-${kind}`;
    message.dir = 'auto';
    message.textContent = text;
    messages.append(message);
    messages.scrollTop = messages.scrollHeight;
  }

  function answer(question, visibleText = question) {
    addMessage(visibleText, 'visitor');
    const intent = matchChatIntent(question, data.intents);
    addMessage(intent?.answer || data.fallback, 'assistant');
  }

  function open() {
    panel.hidden = false;
    launcher.setAttribute('aria-expanded', 'true');
    input.focus();
  }

  function close() {
    panel.hidden = true;
    launcher.setAttribute('aria-expanded', 'false');
    launcher.focus();
  }

  root.hidden = false;
  launcher.addEventListener('click', () => panel.hidden ? open() : close());
  closeButton.addEventListener('click', close);
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && !panel.hidden) close();
  });
  form.addEventListener('submit', event => {
    event.preventDefault();
    const question = input.value.trim();
    if (!question) return;
    answer(question);
    input.value = '';
  });
  root.querySelectorAll('[data-chat-intent]').forEach(button => {
    button.addEventListener('click', () => {
      const intent = data.intents.find(item => item.id === button.dataset.chatIntent);
      if (intent) answer(intent.prompt, intent.prompt);
      input.focus();
    });
  });
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeChatbot, { once: true });
  } else {
    initializeChatbot();
  }
}
